using System;using System.Reflection;using System.Drawing;using System.Windows.Forms;using System.IO;using System.Linq;using System.Numerics;using System.Globalization;using CircuitoStudio;
class NetworkFlowTests {
static int n;static void Check(bool ok,string label){n++;if(!ok)throw new Exception(label);}static void Near(double a,double b,string label){Check(Math.Abs(a-b)<=1e-6*Math.Max(1,Math.Abs(b)),label);}static void Reject(Action action,string label){bool bad=false;try{action();}catch(InvalidDataException){bad=true;}Check(bad,label);}
static NetworkFlowSettings Settings(double voltage){return new NetworkFlowSettings{NominalLineVoltageV=voltage,FrequencyHz=60,SourcePhaseROhm=.05,SourcePhaseXOhm=0,SourceNeutralROhm=.05,SourceNeutralXOhm=0,NeutralModel=FlowNeutralModel.Explicit,Reference="Fonte permanente sintética QA",DataVersion="2026.10",Conditions="Estrela desacoplada4fios; R/X permanentes60Hz, sem controle"};}
static CircuitConductors W(LiveConnection connection,bool neutral=true){return new CircuitConductors{Connection=connection,HasNeutral=neutral,HasPE=true,HasPEN=false,Insulation=EquipmentInsulation.ClassI,Reference="Condutores QA"};}
static void Cable(Circuit c,double r=1,double x=0,double rn=1,double xn=0){c.Cable.ResistanceOhmKm=r;c.Cable.ReactanceOhmKm=x;c.Cable.Reference="Cabo permanente QA";c.Cable.AmpacityA=80;c.ReturnSizing=new ReturnSizingBinding{Engine=ReturnSizing.EngineId,Requirements=new ReturnSizingRequirements(),Neutral=new ReturnConductorRating{Role=ReturnRole.Neutral,Material=ConductorMaterial.Copper,SectionMm2=35,CorrectedIzA=80,ResistanceOhmKm=rn,ReactanceOhmKm=xn,Reference="N-QA",Source="QA",DataVersion="2026.10",Conditions="Regime permanente60Hz"}};}
static Project Base(double voltage){var p=new Project();p.Source.LineVoltage=voltage;p.Source.ShortCircuitKA=10;p.GroundingSource=new GroundingSource{Scheme=EarthingScheme.TNS,NeutralConnection=NeutralEarthConnection.Direct,NeutralDistributed=true,Reference="QA",DataVersion="2026.10",Conditions="N de origem conhecida"};p.Earthing="TN-S";p.FlowSettings=Settings(voltage);return p;}
static NetworkFlowLoad Load(FlowConnection connection,FlowLoadModel model=FlowLoadModel.ConstantPower,FaultLive second=FaultLive.L2){return new NetworkFlowLoad{Connection=connection,Model=model,SecondPhase=second,Reference="Carga elétrica QA",Conditions="Potência nominal/modelo declarados"};}
static Project Single(){var p=Base(230*Math.Sqrt(3));var board=new Board{Id="Q",Voltage=p.Source.LineVoltage};var c=new Circuit{Id="C",PowerKw=2.3,Voltage=230,Phases=PhaseMode.Monofasico,PhaseLabel="L1",LengthM=100,CableMm2=35,FlowLoad=Load(FlowConnection.SingleLN),Conductors=W(LiveConnection.LineNeutral)};Cable(c);board.Circuits.Add(c);p.Boards.Add(board);return p;}
static Project Mixed(){var p=Base(400);p.FlowSettings.SourcePhaseROhm=.015;p.FlowSettings.SourcePhaseXOhm=.02;p.FlowSettings.SourceNeutralROhm=.02;p.FlowSettings.SourceNeutralXOhm=.01;var a=new Board{Id="A",Voltage=400};var b=new Board{Id="B",Voltage=400};var d=new Board{Id="D",Voltage=400};p.Boards.AddRange(new[]{a,b,d});var ab=DiagramEditing.Connect(p,a,b);var bd=DiagramEditing.Connect(p,b,d);foreach(var f in new[]{ab,bd}){f.PowerKw=999;f.DemandFactor=.1;f.CableMm2=35;f.Conductors=W(LiveConnection.ThreePhaseNeutral);}ab.LengthM=50;Cable(ab,.5,.08,1,.08);bd.LengthM=30;Cable(bd,.8,.08,1.2,.08);var l1=new Circuit{Id="L1",PowerKw=2,PowerFactor=.9,DemandFactor=.8,Voltage=400/Math.Sqrt(3),Phases=PhaseMode.Monofasico,PhaseLabel="L1",LengthM=25,CableMm2=35,FlowLoad=Load(FlowConnection.SingleLN),Conductors=W(LiveConnection.LineNeutral)};var l2=new Circuit{Id="L2",PowerKw=1,PowerFactor=.95,DemandFactor=.5,Voltage=400/Math.Sqrt(3),Phases=PhaseMode.Monofasico,PhaseLabel="L2",LengthM=20,CableMm2=35,FlowLoad=Load(FlowConnection.SingleLN),Conductors=W(LiveConnection.LineNeutral)};var tri=new Circuit{Id="DELTA",PowerKw=5,PowerFactor=.85,Voltage=400,Phases=PhaseMode.Trifasico,PhaseLabel="ABC",LengthM=30,CableMm2=35,FlowLoad=Load(FlowConnection.Delta),Conductors=W(LiveConnection.ThreePhase,false)};var ll=new Circuit{Id="LL",PowerKw=1.5,PowerFactor=.9,Voltage=400,Phases=PhaseMode.Monofasico,PhaseLabel="L2",LengthM=35,CableMm2=35,FlowLoad=Load(FlowConnection.SingleLL,FlowLoadModel.ConstantPower,FaultLive.L3),Conductors=W(LiveConnection.LineLine,false)};var cap=new Circuit{Id="CAP",PowerKw=0,ReactiveKvarOverride=-3,Voltage=400,Phases=PhaseMode.Trifasico,PhaseLabel="ABC",LengthM=40,CableMm2=35,FlowLoad=Load(FlowConnection.Delta,FlowLoadModel.ConstantImpedance),Conductors=W(LiveConnection.ThreePhase,false)};foreach(var c in new[]{l1,l2,tri,ll,cap}){Cable(c,1.2,.08,1.8,.08);if(c.Conductors.HasNeutral==false)c.ReturnSizing=null;d.Circuits.Add(c);}return p;}
static string folder;
static void Artifact(Project p,string name){var flow=NetworkFlow.Run(p);Check(flow.Converged,"artifact must converge "+name+": "+flow.Detail);p.Save(Path.Combine(folder,name+".circuito"));Func<double,string> fmt=x=>x.ToString("R",CultureInfo.InvariantCulture);using(var writer=new StreamWriter(Path.Combine(folder,name+".csv"))){writer.WriteLine("Circuit;I1Re;I1Im;I2Re;I2Im;I3Re;I3Im;INRe;INIm;V1Re;V1Im;V2Re;V2Im;V3Re;V3Im;VNRe;VNIm;NominalLegV;Operating1V;Operating2V;Operating3V;DropPercent;MinimumPu;MaximumPu;LossW;LossVar");foreach(var row in flow.Circuits){var values=new System.Collections.Generic.List<string>{row.Circuit.Id};foreach(var current in row.Current){values.Add(fmt(current.Real));values.Add(fmt(current.Imaginary));}foreach(var v in row.EndVoltage){values.Add(fmt(v.Real));values.Add(fmt(v.Imaginary));}values.Add(fmt(row.NominalLegVoltageV));for(int i=0;i<3;i++)values.Add(i<row.OperatingVoltagesV.Length?fmt(row.OperatingVoltagesV[i]):"");values.AddRange(new[]{fmt(row.MaximumAbsDropPercent),fmt(row.MinimumVoltagePu),fmt(row.MaximumVoltagePu),fmt(row.LossVA.Real),fmt(row.LossVA.Imaginary)});writer.WriteLine(String.Join(";",values));}}File.WriteAllText(Path.Combine(folder,name+".txt"),flow.Detail);using(var writer=new StreamWriter(Path.Combine(folder,name+"-totals.csv"))){writer.WriteLine("SourceW;SourceVar;LoadW;LoadVar;LossW;LossVar;PowerResidualVA;KvlResidualV;Iterations");writer.WriteLine(String.Join(";",new[]{flow.SourceVA.Value.Real,flow.SourceVA.Value.Imaginary,flow.LoadVA.Value.Real,flow.LoadVA.Value.Imaginary,flow.LossVA.Value.Real,flow.LossVA.Value.Imaginary,flow.PowerResidualVA.Value,flow.KvlResidualV.Value,flow.Iterations}.Select(fmt)));}}
[STAThread]static int Main(){try{folder=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"referencias-fluxo");Directory.CreateDirectory(folder);var p=Single();var c=p.Boards[0].Circuits[0];var flow=NetworkFlow.Run(p);Check(flow.Converged,"single LN converges: "+flow.Detail);double loadVoltage=(230+Math.Sqrt(230*230-4*.3*2300))/2;double current=2300/loadVoltage;Near(flow.For(c).OperatingVoltagesV[0],loadVoltage,"LN quadratic exact voltage");Near(flow.For(c).Current[0].Real,current,"LN actual current at receiving voltage");Near(flow.For(c).Current[3].Real,-current,"neutral opposite current");Near(flow.LossVA.Value.Real,.3*current*current,"source and cable neutral losses");Near(flow.SourceVA.Value.Real,2300+flow.LossVA.Value.Real,"source power includes losses");Near(flow.LoadVA.Value.Real,2300,"constant power demand once");Check(flow.For(c).Current[0].Real>c.DesignCurrentA,"not nominal current reused");Check(flow.PowerResidualVA<.001&&flow.KvlResidualV<=p.FlowSettings.VoltageToleranceV,"power and KVL residuals checked");Artifact(p,"single-LN");c.FlowLoad.Model=FlowLoadModel.ConstantImpedance;double impedanceV=230/(1+.3*2300/(230*230));Near(NetworkFlow.Run(p).For(c).OperatingVoltagesV[0],impedanceV,"constant impedance analytical divider");Check(NetworkFlow.Run(p).LoadVA.Value.Real<2300,"impedance active power depends on voltage");Artifact(p,"single-impedance");c.FlowLoad.Model=FlowLoadModel.ConstantPower;var before=c.PowerKw;var selected=c.ReturnSizing;NetworkFlow.Run(p);Check(c.PowerKw==before&&Object.ReferenceEquals(c.ReturnSizing,selected),"solver no input mutation");p.FlowSettings.NeutralModel=FlowNeutralModel.Ideal;p.FlowSettings.IdealNeutralReference="Hipótese ideal explícita QA";double idealVoltage=(230+Math.Sqrt(230*230-4*.15*2300))/2;Near(NetworkFlow.Run(p).For(c).OperatingVoltagesV[0],idealVoltage,"ideal neutral only on explicit model");p.FlowSettings.IdealNeutralReference="";Check(!NetworkFlow.Run(p).Converged,"unjustified ideal neutral pending");p.FlowSett