p=Base(400);var board=new Board{Id="Q",Voltage=400};c=new Circuit{Id="DELTA",PowerKw=10,Voltage=400,Phases=PhaseMode.Trifasico,PhaseLabel="ABC",LengthM=0,CableMm2=35,Conductors=W(LiveConnection.ThreePhase,false),FlowLoad=Load(FlowConnection.Delta)};board.Circuits.Add(c);p.Boards.Add(board);p.FlowSettings.NeutralModel=FlowNeutralModel.NoNeutralLoads;p.FlowSettings.SourcePhaseROhm=.1;p.FlowSettings.SourcePhaseXOhm=0;p.FlowSettings.SourceNeutralROhm=p.FlowSettings.SourceNeutralXOhm=null;p.GroundingSource.NeutralDistributed=false;flow=NetworkFlow.Run(p);Check(flow.Converged,"delta without neutral");double u0=400/Math.Sqrt(3),vp=(u0+Math.Sqrt(u0*u0-4*.1*10000/3))/2;Near(flow.For(c).OperatingVoltagesV[0],Math.Sqrt(3)*vp,"balanced delta quadratic reference");Near(flow.For(c).NeutralCurrentA,0,"delta no neutral by connection");Near(flow.SourceVA.Value.Real,10000+flow.LossVA.Value.Real,"balanced delta losses");Artifact(p,"balanced-delta");c.PowerKw=0;c.ReactiveKvarOverride=-3;p.FlowSettings.SourcePhaseROhm=0;p.FlowSettings.SourcePhaseXOhm=.2;double capacitorVp=(u0+Math.Sqrt(u0*u0+4*.2*3000/3))/2;flow=NetworkFlow.Run(p);Near(flow.For(c).OperatingVoltagesV[0],Math.Sqrt(3)*capacitorVp,"capacitive voltage rise analytical root");Check(flow.For(c).MaximumVoltagePu>1&&flow.For(c).MaximumAbsDropPercent>0,"rise and positive absolute limit metric");
p=Mixed();flow=NetworkFlow.Run(p);Check(flow.Converged,"three-level mixed converges: "+flow.Detail);var feeder=p.Boards[0].Circuits[0];var last=p.Boards[2].Circuits.Single(x=>x.Id=="L1");Check(flow.For(feeder).NeutralCurrentA>1,"unbalance produces shared neutral current");Check(flow.For(feeder).MaximumPhaseCurrentA>flow.For(feeder).Current.Take(3).Average(x=>Complex.Abs(x)),"peak phase not mean current");Near(flow.LoadVA.Value.Real,8600,"terminal demand and feeder placeholders not doubled");Check(flow.For(last).OperatingVoltagesV[0]<400/Math.Sqrt(3),"voltage propagated through three levels");var cap=p.Boards[2].Circuits.Single(x=>x.Id=="CAP");Check(flow.For(cap).ReceivingVA.Imaginary<0,"capacitor negative reactive flow");Check(Math.Abs(flow.For(cap).ReceivingVA.Imaginary+3000)>1,"impedance capacitor follows actual voltage");Artifact(p,"mixed-three-level");var triModel=p.Boards[2].Circuits.Single(x=>x.Id=="DELTA");Near(flow.For(triModel).NeutralCurrentA,0,"delta current sum zero by wiring");triModel.FlowLoad.Connection=FlowConnection.WyeNeutral;triModel.Conductors.Connection=LiveConnection.ThreePhaseNeutral;triModel.Conductors.HasNeutral=true;Cable(triModel,1.2,.08,1.8,.08);var wye=NetworkFlow.Run(p);Check(wye.Converged&&wye.For(triModel).NeutralCurrentA>1e-5,"wye neutral differs from delta under unbalance");Artifact(p,"mixed-wye-neutral");triModel.FlowLoad.Connection=FlowConnection.Delta;triModel.Conductors.Connection=LiveConnection.ThreePhase;triModel.Conductors.HasNeutral=false;triModel.ReturnSizing=null;var expected=flow.For(last).OperatingVoltagesV[0];feeder.PowerKw=123456;feeder.DemandFactor=.001;Near(NetworkFlow.Run(p).For(last).OperatingVoltagesV[0],expected,"feeder power/demand ignored consistently");feeder.PowerKw=999;feeder.DemandFactor=.1;var phaseMode=feeder.Phases;feeder.Phases=PhaseMode.Monofasico;Reject(()=>NetworkFlow.Run(p),"single phase feeder cannot supply modeled three phase board");feeder.Phases=phaseMode;string selectedMemory=EngineeringReport.Memory(p,Engineering.Analyze(p),new System.Collections.Generic.HashSet<string>(new[]{last.Id}));Check(selectedMemory.Contains(last.Id+" — ")&&!selectedMemory.Contains("DELTA — "),"selected flow details honor selection");string svg=Path.Combine(folder,"nominal.svg");DiagramSvg.Save(p,p.Boards[2],svg);Check(File.ReadAllText(svg).Contains("Valores nominais; fluxo por fase"),"diagram distinguishes nominal values from solved flow");var original=p.Boards[2].Circuits.Single(x=>x.Id=="L2").PhaseLabel;p.Boards[2].Circuits.Single(x=>x.Id=="L2").PhaseLabel="L3";Check(Math.Abs(NetworkFlow.Run(p).For(last).OperatingVoltagesV[0]-expected)>1e-6,"phase change affects shared neutral and voltages");p.Boards[2].Circuits.Single(x=>x.Id=="L2").PhaseLabel=original;string file=Path.Combine(folder,"mixed-three-level.circuito");var restored=Project.Load(file);Near(NetworkFlow.Run(restored).For(restored.Boards[2].Circuits.Single(x=>x.Id=="L1")).OperatingVoltagesV[0],expected,"reopen exact solution");Check(File.ReadAllText(file).Contains("network-flow-v1"),"capability declared");Check(EngineeringReport.Memory(p,Engineering.Analyze(p))==EngineeringReport.Memory(restored,Engineering.Analyze(restored)),"flow memory exact after reopen");var report=EngineeringReport.Memory(p,Engineering.Analyze(p));Check(report.Contains("FLUXO POR FASE E NEUTRO")&&report.Contains("não é N RMS total"),"report method and neutral limitation");var partial=NetworkFlow.Run(p);Check(p.Boards[2].Circuits.Single(x=>x.Id=="L1").ReturnSizing.Requirements.NeutralDesignRmsA==null,"no automatic conversion of fundamental N into RMS sizing");string export=Path.Combine(folder,"exportado.csv");NetworkFlow.Export(p,export);NetworkFlow.Export(p,export);var exported=File.ReadAllBytes(export);var backup=File.ReadAllBytes(export+".bak");var settings=p.FlowSettings;p.FlowSettings=null;Check(!NetworkFlow.Run(p).Converged,"load options without global source stay pending");Reject(()=>NetworkFlow.Export(p,export),"failed flow cannot export accepted numbers");Check(File.ReadAllBytes(export).SequenceEqual(exported)&&File.ReadAllBytes(export+".bak").SequenceEqual(backup),"failed flow preserves export and backup");p.FlowSettings=settings;string engine=p.FlowSettings.Engine;p.FlowSettings.Engine="future";Reject(p.Validate,"unknown global flow evaluator");p.FlowSettings.Engine=engine;var options=last.FlowLoad;last.FlowLoad=null;Check(!NetworkFlow.Run(p).Converged,"unknown load connection/model not inferred");last.FlowLoad=options;string loadEngine=last.FlowLoad.Engine;last.FlowLoad.Engine="future";Reject(p.Validate,"unknown load evaluator");last.FlowLoad.Engine=loadEngine;double? oldX=p.FlowSettings.SourcePhaseXOhm;p.FlowSettings.SourcePhaseXOhm=null;Check(!NetworkFlow.Run(p).Converged,"source phase X unknown not zero");p.FlowSettings.SourcePhaseXOhm=oldX;p.FlowSettings.SourcePhaseROhm=-1;Reject(p.Validate,"negative source resistance");p.FlowSettings.SourcePhaseROhm=.015;var oldIterations=p.FlowSettings.MaximumIterations;p.FlowSettings.MaximumIterations=0;Reject(p.Validate,"invalid iteration limit");p.FlowSettings.MaximumIterations=oldIterations;var oldReference=p.FlowSettings.Reference;p.FlowSettings.Reference="PREENCHER fonte";Check(!NetworkFlow.Run(p).Converged,"unfilled source template pending");p.FlowSettings.Reference=oldReference;var llModel=p.Boards[2].Circuits.Single(x=>x.Id=="LL");llModel.FlowLoad.SecondPhase=FaultLive.L2;Check(!NetworkFlow.Run(p).Converged,"LL phase pair cannot repeat same phase");llModel.FlowLoad.SecondPhase=FaultLive.L3;var clone=ProjectEditing.DuplicateCircuit(p,p.Boards[2],last);Check(clone.FlowLoad!=last.FlowLoad&&clone.FlowLoad.Connection==FlowConnection.SingleLN,"independent load options copy");p.Boards[2].Circuits.Remove(clone);string previous=Environment.GetEnvironmentVariable("CIRCUITO_QA_PREVIOUS_EXE");if(!String.IsNullOrEmpty(previous)){var assembly=Assembly.LoadFile(Path.GetFullPath(previous));bool rejected=false;try{assembly.GetType("CircuitoStudio.Project").GetMetho